const canvas = document.querySelector("[data-hook=image-view]");
const pen = canvas.getContext("2d");
const status = document.getElementById("status");
let name = "photo";
let opened = false;
const load = (url) => new Promise((resolve, reject) => {
  const image = new Image();
  image.onload = () => resolve(image);
  image.onerror = reject;
  image.src = url;
});
const say = (text) => { status.textContent = text; };
const needsPhoto = () => { if (!opened) say("Open a photo first."); return !opened; };
document.querySelector("[data-hook=image-open]").addEventListener("click", async () => {
  try {
    const file = await tessera.pickFile();
    if (!file) return say("No photo was picked.");
    const image = await load(await tessera.assetUrl(file.id));
    canvas.width = image.naturalWidth;
    canvas.height = image.naturalHeight;
    pen.drawImage(image, 0, 0);
    name = file.name.replace(/\.[A-Za-z0-9]+$/, "");
    opened = true;
    say("Opened " + file.name + ", " + file.widthPx + " by " + file.heightPx + " pixels.");
  } catch (error) {
    say(error.message);
  }
});
// Keeps the middle of the photo, four fifths of each side.
document.querySelector("[data-hook=image-edit]").addEventListener("click", () => {
  if (needsPhoto()) return;
  const width = Math.max(1, Math.round(canvas.width * 0.8));
  const height = Math.max(1, Math.round(canvas.height * 0.8));
  const copy = document.createElement("canvas");
  copy.width = canvas.width;
  copy.height = canvas.height;
  copy.getContext("2d").drawImage(canvas, 0, 0);
  canvas.width = width;
  canvas.height = height;
  pen.drawImage(copy, (copy.width - width) / 2, (copy.height - height) / 2, width, height, 0, 0, width, height);
  say("Cropped to " + width + " by " + height + " pixels.");
});
document.getElementById("arrow").addEventListener("click", () => {
  if (needsPhoto()) return;
  const size = Math.min(canvas.width, canvas.height);
  const [x, y] = [canvas.width / 2, canvas.height / 2];
  pen.strokeStyle = "#d62828";
  pen.fillStyle = "#d62828";
  pen.lineWidth = Math.max(2, size / 20);
  pen.beginPath();
  pen.moveTo(x - size / 3, y + size / 3);
  pen.lineTo(x, y);
  pen.stroke();
  pen.beginPath();
  pen.moveTo(x, y);
  pen.lineTo(x - size / 8, y);
  pen.lineTo(x, y + size / 8);
  pen.closePath();
  pen.fill();
  say("Added an arrow.");
});
document.getElementById("text").addEventListener("click", () => {
  if (needsPhoto()) return;
  const text = document.getElementById("caption").value.trim();
  if (!text) return say("Write the text first.");
  pen.fillStyle = "#ffffff";
  pen.strokeStyle = "#000000";
  pen.font = "bold " + Math.max(10, Math.round(canvas.height / 6)) + "px sans-serif";
  pen.lineWidth = 2;
  pen.strokeText(text, 4, canvas.height - 6);
  pen.fillText(text, 4, canvas.height - 6);
  say("Added the text.");
});
document.querySelector("[data-hook=image-save]").addEventListener("click", async () => {
  if (needsPhoto()) return;
  try {
    const saved = await tessera.saveFile({
      name: name + "-edited.png",
      type: "image/png",
      bytesBase64: canvas.toDataURL("image/png").split(",")[1],
    });
    say(saved ? "Saved " + name + "-edited.png." : "Not saved.");
  } catch (error) {
    say(error.message);
  }
});

